# patch-email.ps1
# Writes 4 email files verbatim via base64 (paste-proof).

$ErrorActionPreference = 'Stop'
cd C:\Users\kevch\Desktop\ProjectFortuna\vendorhub

$files = @{
  'src\lib\email\client.ts' = ''
  'src\lib\email\templates\offer-received.tsx' = ''
  'src\lib\email\templates\offer-accepted.tsx' = ''
  'src\lib\email\templates\verification-approved.tsx' = ''
}

foreach ($entry in $files.GetEnumerator()) {
  $path = $entry.Key
  $b64 = $entry.Value
  $content = [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($b64))
  $dir = [System.IO.Path]::GetDirectoryName($path)
  if ($dir -and -not (Test-Path -LiteralPath $dir)) {
    New-Item -ItemType Directory -Force -Path $dir | Out-Null
  }
  Set-Content -LiteralPath $path -Value $content -Encoding UTF8 -NoNewline
  $size = (Get-Item -LiteralPath $path).Length
  Write-Host "Wrote $path ($size bytes)" -ForegroundColor Green
}

Write-Host ''
Write-Host 'All 4 email files written.' -ForegroundColor Cyan